"""Load a JSON config from disk, falling back to built-in defaults."""

from __future__ import annotations

import json
import logging
import os
from typing import Any, Dict

logger = logging.getLogger(__name__)

DEFAULT_CONFIG: Dict[str, Any] = {
    "host": "127.0.0.1",
    "port": 8080,
    "workers": 4,
    "debug": False,
    "log_level": "INFO",
}


class ConfigError(Exception):
    """Raised when a config file exists but cannot be used."""


def _merge(defaults: Dict[str, Any], overrides: Dict[str, Any]) -> Dict[str, Any]:
    merged = dict(defaults)
    for key, value in overrides.items():
        if isinstance(value, dict) and isinstance(merged.get(key), dict):
            merged[key] = _merge(merged[key], value)
        else:
            merged[key] = value
    return merged


def load_config(path: str | os.PathLike[str], defaults: Dict[str, Any] | None = None) -> Dict[str, Any]:
    """Return the config at `path` layered over `defaults`.

    A missing file is not an error: the defaults are returned unchanged.
    Malformed JSON is, since silently ignoring it would hide a typo in a
    file the user deliberately wrote.
    """
    base = DEFAULT_CONFIG if defaults is None else defaults

    try:
        with open(path, encoding="utf-8") as handle:
            loaded = json.load(handle)
    except FileNotFoundError:
        logger.info("No config at %s; using defaults", path)
        return dict(base)
    except json.JSONDecodeError as exc:
        raise ConfigError(f"{path} is not valid JSON: {exc}") from exc
    except OSError as exc:
        raise ConfigError(f"could not read {path}: {exc}") from exc

    if not isinstance(loaded, dict):
        raise ConfigError(f"{path} must contain a JSON object, got {type(loaded).__name__}")

    return _merge(base, loaded)
